@code {
    private AppointmentModel Model { get; set; } = new();
    private EditContext editContext = default!;
    private CustomValidator? customValidator;

    private bool showStep2;
    private bool isProcessing;
    private bool isBooked;
    private List<string> doctors = [];
    private List<string> availableSlots = [];

    // Fields that belong to step 1 for partial validation
    private static readonly string[] Step1Fields =
        [nameof(AppointmentModel.PatientName), nameof(AppointmentModel.Email),
         nameof(AppointmentModel.Phone), nameof(AppointmentModel.InsuranceProvider)];

    protected override void OnInitialized()
    {
        editContext = new EditContext(Model);
    }

    private async Task CheckAvailability()
    {
        customValidator?.ClearErrors();

        // Validate only step-1 fields via data annotations
        var step1Valid = ValidateStep1();
        if (!step1Valid)
        {
            return;
        }

        isProcessing = true;
        try
        {
            doctors = await AppointmentService.GetDoctorsAsync();
            showStep2 = true;
        }
        finally
        {
            isProcessing = false;
        }
    }

    private bool ValidateStep1()
    {
        var validationResults = new List<ValidationResult>();
        var isValid = true;

        foreach (var fieldName in Step1Fields)
        {
            var fieldIdentifier = editContext.Field(fieldName);
            editContext.NotifyFieldChanged(fieldIdentifier);
            if (editContext.GetValidationMessages(fieldIdentifier).Any())
            {
                isValid = false;
            }
        }

        // Also run DataAnnotations manually for step-1 properties
        var properties = Step1Fields
            .Select(f => typeof(AppointmentModel).GetProperty(f))
            .Where(p => p is not null);

        foreach (var prop in properties)
        {
            var value = prop!.GetValue(Model);
            var context = new ValidationContext(Model) { MemberName = prop.Name };
            if (!Validator.TryValidateProperty(value, context, validationResults))
            {
                isValid = false;
            }
        }

        if (!isValid)
        {
            editContext.Validate();
        }

        return isValid;
    }

    private async Task OnDoctorChanged()
    {
        await LoadSlots();
    }

    private async Task OnDateChanged()
    {
        await LoadSlots();
    }

    private async Task LoadSlots()
    {
        Model.TimeSlot = null;
        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentService.GetAvailableSlotsAsync(
                Model.Doctor, Model.AppointmentDate.Value);
        }
        else
        {
            availableSlots = [];
        }
    }

    private async Task HandleSubmit()
    {
        customValidator?.ClearErrors();

        if (!editContext.Validate())
        {
            return;
        }

        isProcessing = true;
        try
        {
            var errors = await AppointmentService.ValidatePatientAsync(
                Model.Email!, Model.InsuranceProvider!, Model.Doctor!, Model.TimeSlot!);

            if (errors.Count > 0)
            {
                customValidator!.DisplayErrors(errors);
                return;
            }

            isBooked = true;
        }
        finally
        {
            isProcessing = false;
        }
    }
}

using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Forms;

namespace sv_da3482addf16492c8afecdd87873603a.Components;

public class CustomValidator : ComponentBase
{
    [CascadingParameter]
    private EditContext? EditContext { get; set; }

    private ValidationMessageStore? messageStore;

    protected override void OnInitialized()
    {
        messageStore = new ValidationMessageStore(EditContext!);
        EditContext!.OnValidationRequested += (s, e) => messageStore.Clear();
        EditContext!.OnFieldChanged += (s, e) => messageStore.Clear(e.FieldIdentifier);
    }

    public void DisplayErrors(Dictionary<string, List<string>> errors)
    {
        foreach (var (field, messages) in errors)
        {
            foreach (var message in messages)
            {
                messageStore!.Add(EditContext!.Field(field), message);
            }
        }
        EditContext!.NotifyValidationStateChanged();
    }

    public void ClearErrors()
    {
        messageStore?.Clear();
        EditContext?.NotifyValidationStateChanged();
    }
}

