@page "/book-appointment"
@rendermode InteractiveServer
@using sv_da3482addf16492c8afecdd87873603a.Services
@inject AppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h1>Book an Appointment</h1>

<EditForm EditContext="editContext" OnSubmit="HandleSubmit" FormName="book-appointment">
    <DataAnnotationsValidator />
    <CustomValidator @ref="customValidator" />

    <fieldset>
        <legend>Patient Information</legend>

        <div class="form-group">
            <label for="patientName">Patient Name</label>
            <InputText id="patientName" @bind-Value="Model.PatientName" class="form-control" />
            <ValidationMessage For="() => Model.PatientName" />
        </div>

        <div class="form-group">
            <label for="email">Email</label>
            <InputText id="email" @bind-Value="Model.Email" class="form-control" />
            <ValidationMessage For="() => Model.Email" />
        </div>

        <div class="form-group">
            <label for="phone">Phone</label>
            <InputText id="phone" @bind-Value="Model.Phone" class="form-control" />
            <ValidationMessage For="() => Model.Phone" />
        </div>

        <div class="form-group">
            <label for="insurance">Insurance Provider</label>
            <InputSelect id="insurance" @bind-Value="Model.InsuranceProvider" class="form-control">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => Model.InsuranceProvider" />
        </div>
    </fieldset>

    @if (!showStep2)
    {
        <button type="button" class="btn btn-primary" @onclick="CheckAvailability" disabled="@isProcessing">
            @(isProcessing ? "Checking..." : "Check Availability")
        </button>
    }

    @if (showStep2)
    {
        <fieldset>
            <legend>Appointment Details</legend>

            <div class="form-group">
                <label for="doctor">Preferred Doctor</label>
                <InputSelect id="doctor" @bind-Value="Model.Doctor" @bind:after="OnDoctorChanged" class="form-control">
                    <option value="">-- Select --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.Doctor" />
            </div>

            <div class="form-group">
                <label for="date">Date</label>
                <InputDate id="date" @bind-Value="Model.AppointmentDate" @bind:after="OnDateChanged" class="form-control" />
                <ValidationMessage For="() => Model.AppointmentDate" />
            </div>

            <div class="form-group">
                <label for="timeslot">Time Slot</label>
                <InputSelect id="timeslot" @bind-Value="Model.TimeSlot" class="form-control" disabled="@(availableSlots.Count == 0)">
                    <option value="">-- Select --</option>
                    @foreach (var slot in availableSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.TimeSlot" />
            </div>

            <div class="form-group">
                <label for="reason">Reason for Visit</label>
                <InputTextArea id="reason" @bind-Value="Model.Reason" class="form-control" rows="3" />
                <ValidationMessage For="() => Model.Reason" />
            </div>
        </fieldset>

        <button type="submit" class="btn btn-primary" disabled="@isProcessing">
            @(isProcessing ? "Submitting..." : "Book Appointment")
        </button>
    }
</EditForm>

@if (isBooked)
{
    <div class="alert alert-success" role="alert">
        Appointment booked successfully!
    </div>
}

@code {
    private AppointmentModel Model { get; set; } = new();
    private EditContext editContext = default!;
    private CustomValidator? customValidator;

    private bool showStep2;
    private bool isProcessing;
    private bool isBooked;
    private List<string> doctors = [];
    private List<string> availableSlots = [];

    // Fields that belong to step 1 for partial validation
    private static readonly string[] Step1Fields =
        [nameof(AppointmentModel.PatientName), nameof(AppointmentModel.Email),
         nameof(AppointmentModel.Phone), nameof(AppointmentModel.InsuranceProvider)];

    protected override void OnInitialized()
    {
        editContext = new EditContext(Model);
    }

    private async Task CheckAvailability()
    {
        customValidator?.ClearErrors();

        // Validate only step-1 fields via data annotations
        var step1Valid = ValidateStep1();
        if (!step1Valid)
        {
            return;
        }

        isProcessing = true;
        try
        {
            doctors = await AppointmentService.GetDoctorsAsync();
            showStep2 = true;
        }
        finally
        {
            isProcessing = false;
        }
    }

    private bool ValidateStep1()
    {
        var validationResults = new List<ValidationResult>();
        var isValid = true;

        foreach (var fieldName in Step1Fields)
        {
            var fieldIdentifier = editContext.Field(fieldName);
            editContext.NotifyFieldChanged(fieldIdentifier);
            if (editContext.GetValidationMessages(fieldIdentifier).Any())
            {
                isValid = false;
            }
        }

        // Also run DataAnnotations manually for step-1 properties
        var properties = Step1Fields
            .Select(f => typeof(AppointmentModel).GetProperty(f))
            .Where(p => p is not null);

        foreach (var prop in properties)
        {
            var value = prop!.GetValue(Model);
            var context = new ValidationContext(Model) { MemberName = prop.Name };
            if (!Validator.TryValidateProperty(value, context, validationResults))
            {
                isValid = false;
            }
        }

        if (!isValid)
        {
            editContext.Validate();
        }

        return isValid;
    }

    private async Task OnDoctorChanged()
    {
        await LoadSlots();
    }

    private async Task OnDateChanged()
    {
        await LoadSlots();
    }

    private async Task LoadSlots()
    {
        Model.TimeSlot = null;
        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentService.GetAvailableSlotsAsync(
                Model.Doctor, Model.AppointmentDate.Value);
        }
        else
        {
            availableSlots = [];
        }
    }

    private async Task HandleSubmit()
    {
        customValidator?.ClearErrors();

        if (!editContext.Validate())
        {
            return;
        }

        isProcessing = true;
        try
        {
            var errors = await AppointmentService.ValidatePatientAsync(
                Model.Email!, Model.InsuranceProvider!, Model.Doctor!, Model.TimeSlot!);

            if (errors.Count > 0)
            {
                customValidator!.DisplayErrors(errors);
                return;
            }

            isBooked = true;
        }
        finally
        {
            isProcessing = false;
        }
    }
}

